CREATE OR REPLACE FUNCTION public.guest_cap(_event uuid) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN e.capacity IS NULL THEN NULL WHEN (public.plan_limits(public.effective_plan(e.host_id)->>'plan')->>'guests') IS NULL OR e.starts_at < coalesce(public.host_no_limits_until(e.host_id), '-infinity'::timestamptz) THEN e.capacity ELSE least(e.capacity, (public.plan_limits(public.effective_plan(e.host_id)->>'plan')->>'guests')::int) END FROM public.events e WHERE e.id=_event $$;
CREATE OR REPLACE FUNCTION public.event_registration_window_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.events; t jsonb; BEGIN IF NEW.status NOT IN ('going','maybe','waitlist','requested') OR (TG_OP='UPDATE' AND NEW.status=OLD.status AND NEW.tier_id IS NOT DISTINCT FROM OLD.tier_id) THEN RETURN NEW; END IF; SELECT * INTO e FROM public.events WHERE id=NEW.event_id; IF e.status <> 'published' THEN RAISE EXCEPTION 'not_open'; END IF; IF e.reg_opens_at IS NOT NULL AND now()<e.reg_opens_at THEN RAISE EXCEPTION 'registration_not_open'; END IF; IF e.reg_closes_at IS NOT NULL AND now()>=e.reg_closes_at THEN RAISE EXCEPTION 'registration_closed'; END IF; IF NEW.tier_id IS NOT NULL THEN SELECT x INTO t FROM jsonb_array_elements(e.ticket_tiers) x WHERE x->>'id'=NEW.tier_id; IF t IS NULL THEN RAISE EXCEPTION 'tier_required'; END IF; IF nullif(t->>'sale_starts_at','') IS NOT NULL AND now()<(t->>'sale_starts_at')::timestamptz THEN RAISE EXCEPTION 'registration_not_open'; END IF; IF nullif(t->>'sale_ends_at','') IS NOT NULL AND now()>=(t->>'sale_ends_at')::timestamptz THEN RAISE EXCEPTION 'registration_closed'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER event_registration_window_guard BEFORE INSERT OR UPDATE ON public.rsvps FOR EACH ROW EXECUTE FUNCTION public.event_registration_window_guard();
COMMENT ON FUNCTION public.guest_cap(uuid) IS 'Explicit unlimited capacity stays NULL; plan guest caps only narrow configured positive limits.';